namespace ghidra.app.plugin.prototype.MicrosoftCodeAnalyzerPlugin;

using ghidra.app.services;
using ghidra.app.util.datatype.microsoft;
using ghidra.app.util.datatype.microsoft.ThreadEnvironmentBlock;
using ghidra.app.util.importer;
using ghidra.framework.options;
using ghidra.program.model.address;
using ghidra.program.model.listing;
using ghidra.program.model.mem;
using ghidra.program.model.mem;
using ghidra.util;
using ghidra.util.exception;
using ghidra.util.task;

public class TEBAnalyzer : AbstractAnalyzer {
	private static readonly string NAME = "Windows x86 Thread Environment Block (TEB) Analyzer";
	private static readonly string DESCRIPTION =
		"Create and mark up a Thread Environment Block. Set FS or GS segments to point to it.";

	protected static readonly string ADDRESS_OPTION_NAME = "Starting Address of the TEB";
	protected static readonly string ADDRESS_OPTION_DESCRIPTION =
		"Address in RAM where TEB is located (must not be mapped to another block)";
	protected static readonly string ADDRESS_OPTION_DEFAULT_VALUE = "";

	protected static readonly string VERSION_OPTION_NAME = "Windows OS Version";
	protected static readonly string VERSION_OPTION_DESCRIPTION =
		"Version of the TEB fields to lay down. Many common fields persist across multiple OS versions.";
	protected static readonly WinVersion VERSION_OPTION_DEFAULT_VALUE = WinVersion.WIN_7;

	protected string tebAddressString = ADDRESS_OPTION_DEFAULT_VALUE;
	protected WinVersion winVersion = VERSION_OPTION_DEFAULT_VALUE;

	public TEBAnalyzer() : base(NAME, DESCRIPTION, AnalyzerType.BYTE_ANALYZER)
    {
		setPriority(AnalysisPriority.FORMAT_ANALYSIS.after().after());
		setDefaultEnablement(true);
	}

	/* @Override */
	public bool canAnalyze(Program program) {
		if (!program.getLanguageID().getIdAsString().startsWith("x86")) {
			return false;
		}
		return PEUtil.isVisualStudioOrClangPe(program);
	}

	private Address findBlockLocation(Program program, bool is64Bit, int blockSize) {
		long offset = is64Bit ? 0xff00000000L : 0xffdff000L;
		Memory memory = program.getMemory();
		AddressSpace addrSpace = program.getAddressFactory().getDefaultAddressSpace();
		Address startAddr = addrSpace.getAddress(offset);
		Address endAddr = startAddr.add(blockSize - 1);
		if (!memory.intersects(startAddr, endAddr)) {
			return startAddr;
		}
		MemoryBlock[] blocks = memory.getBlocks();
		foreach (MemoryBlock block in blocks) {
			Address addr = block.getEnd();
			if (addr.getAddressSpace() != addrSpace) {
				continue;
			}
			if (startAddr.compareTo(addr) < 0) {
				startAddr = addr;
			}
		}
		startAddr = startAddr.add(1);
		return startAddr;
	}

	private void setTEBAddress(Program program, ThreadEnvironmentBlock teb) {
		long offset;
		try {
			offset = Long.parseLong(tebAddressString, 16);
		}
		catch (NumberFormatException ex) {
			offset = 0;		// Option is empty or bad format
		}
		Address addr;
		if (offset == 0) {
			addr = findBlockLocation(program, teb.is64(), teb.getBlockSize());
		}
		else {
			addr = program.getAddressFactory().getDefaultAddressSpace().getAddress(offset);
		}
		teb.setAddress(addr);
	}

	/* @Override */
	public bool added(Program program, AddressSetView set, TaskMonitor monitor, MessageLog log)
    {
		if (!program.hasExclusiveAccess()) {
			log.appendMsg(
				"WARNING: Unable to perform Thread Environment Block (TEB) analysis - exclusive checkout required");
			return false;
		}

		MemoryBlock block = program.getMemory().getBlock(ThreadEnvironmentBlock.BLOCK_NAME);
		if (block != null) {
			return true;
		}

		try {
			ThreadEnvironmentBlock teb = new ThreadEnvironmentBlock(program, winVersion);
			setTEBAddress(program, teb);
			teb.createBlocksAndSymbols();
			teb.setRegisterValue();
			return true;
		}
		catch (Exception e) {
			log.appendMsg("Failed to create the Thread Environment Block (TEB) - see console log");
			Msg.error(this, "Failed to create the Thread Environment Block (TEB)", e);
		}
		return false;
	}

	/* @Override */
	public void registerOptions(Options options, Program program) {
		options.registerOption(ADDRESS_OPTION_NAME, tebAddressString, null,
			ADDRESS_OPTION_DESCRIPTION);
		options.registerOption(VERSION_OPTION_NAME, winVersion, null, VERSION_OPTION_DESCRIPTION);
	}

	/* @Override */
	public void optionsChanged(Options options, Program program) {
		tebAddressString = options.getString(ADDRESS_OPTION_NAME, tebAddressString);
		winVersion = options.getEnum(VERSION_OPTION_NAME, winVersion);
	}
}
